package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class Cleaner_clean_TriageGen1Test {

    @Test(expected = NullPointerException.class)
    public void clean_nullDocument_throwsException() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        cleaner.clean(null);
    }

    @Test
    public void clean_emptyDocument_returnsCleanDocument() {
        Cleaner cleaner = new Cleaner(Safelist.none());
        Document dirty = Jsoup.parse("");
        Document clean = cleaner.clean(dirty);

        assertNotNull(clean);
        assertEquals(dirty.baseUri(), clean.baseUri());
        assertEquals("", clean.body().html());
    }

    @Test
    public void clean_safeHtml_returnsIdenticalBody() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        String html = "<p>Hello <b>World</b></p>";
        Document dirty = Jsoup.parse(html);
        Document clean = cleaner.clean(dirty);

        assertEquals(dirty.baseUri(), clean.baseUri());
        // Note: Jsoup might normalize formatting, so we compare the inner HTML structure
        assertEquals(dirty.body().html(), clean.body().html());
    }

    @Test
    public void clean_unsafeHtml_removesUnsafeTags() {
        Cleaner cleaner = new Cleaner(Safelist.none());
        String html = "<div><p>Keep</p><script>alert(1)</script></div>";
        Document dirty = Jsoup.parse(html);
        Document clean = cleaner.clean(dirty);

        // Safelist.none() removes all tags, so body should be empty or just text
        String cleanHtml = clean.body().html();
        assertFalse(cleanHtml.contains("<script>"));
        assertFalse(cleanHtml.contains("<div>"));
        assertFalse(cleanHtml.contains("<p>"));
        assertTrue(cleanHtml.contains("Keep"));
    }

    @Test
    public void clean_preservesBaseUri() {
        Cleaner cleaner = new Cleaner(Safelist.basic());
        Document dirty = Jsoup.parse("<html></html>");
        dirty.setBaseUri("https://example.com/path/to/page.html");

        Document clean = cleaner.clean(dirty);

        assertEquals("https://example.com/path/to/page.html", clean.baseUri());
    }

    @Test
    public void clean_complexStructure_cleansCorrectly() {
        Cleaner cleaner = new Cleaner(Safelist.simpleText());
        String html = "<ul><li>Item 1</li><li><a href='http://unsafe.com'>Link</a></li></ul>";
        Document dirty = Jsoup.parse(html);
        Document clean = cleaner.clean(dirty);

        String cleanHtml = clean.body().html();
        // simpleText allows text but no tags like ul or li
        assertFalse(cleanHtml.contains("<ul>"));
        assertFalse(cleanHtml.contains("<li>"));
        assertFalse(cleanHtml.contains("<a>"));
        assertTrue(cleanHtml.contains("Item 1"));
        assertTrue(cleanHtml.contains("Link"));
    }
}
